test('payment timeout', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.paymentTimeout('a')).ok, false);
  await h.checkout('a');
  assert.equal((await h.paymentTimeout('a')).ok, false);
  await h.deliver((await h.inFlight())[0].id); // Reserve
  await h.deliver((await h.inFlight())[0].id); // Reserved
  assert.deepEqual(await h.paymentTimeout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'abandoning', items: 2 });
  for (const c of ['add', 'checkout', 'cancel', 'returnCart', 'retry', 'abandon', 'paymentTimeout']) assert.equal((await h[c]('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 2 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  // declined after the timeout
  await h.open('b'); await h.add('b'); await h.checkout('b'); await h.deliverAll();
  await h.declineCards(); await h.retry('b');
  assert.equal((await h.cart('b')).status, 'declined');
});

