import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('happy path and messages', async () => {
  const h = await createHost();
  assert.deepEqual(await h.cart('a'), null);
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.checkout('a'), { ok: true });
  const m = await h.inFlight();
  assert.equal(m.length, 1);
  assert.deepEqual({ ...m[0], id: 0 }, { id: 0, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliver(m[0].id);
  const m2 = await h.inFlight();
  assert.equal(m2[0].action, 'Reserved'); assert.equal(m2[0].to, 'a');
  await h.deliver(m2[0].id);
  assert.equal((await h.cancel('a')).ok, false);
  const m3 = await h.inFlight();
  assert.deepEqual(m3[0].data, { from: 'a', amount: 2 });
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
  await h.open('b'); await h.add('b'); await h.checkout('b'); await h.deliverAll();
  assert.equal((await h.cart('b')).status, 'failed');
});

